#[rustfmt::skip]
pub fn holds(i: usize, v: &[Val<'_>], t: &Target) -> bool {
    match i {
        0 => !(cmp(Cmp::Eq, v[1], Val::Bool(true)) && cmp(Cmp::Eq, v[2], Val::Bool(true))),
        1 => !(cmp(Cmp::Eq, v[3], Val::Bool(true)) && (cmp(Cmp::Eq, v[1], Val::Bool(true)) || cmp(Cmp::Eq, v[2], Val::Bool(true)))),
        2 => !cmp(Cmp::Gt, v[8], Val::Nat(1)) || cmp(Cmp::Eq, v[29], Val::Bool(true)),
        3 => !cmp(Cmp::Eq, v[18], Val::Bool(true)) || (TargetAtom::Arch("gfx950").eval(t) && cmp(Cmp::Eq, v[17], Val::Bool(true))),
        4 => !cmp(Cmp::Eq, v[19], Val::Bool(true)) || (TargetAtom::Arch("gfx950").eval(t) && cmp(Cmp::Eq, v[18], Val::Bool(true)) && cmp(Cmp::Eq, v[20], Val::Bool(true)) && cmp(Cmp::Eq, v[28], Val::Bool(true))),
        5 => !cmp(Cmp::Eq, v[20], Val::Bool(true)) || (cmp(Cmp::Eq, v[17], Val::Bool(true)) && !cmp(Cmp::Eq, v[29], Val::Bool(true))),
        6 => !cmp(Cmp::Eq, v[21], Val::Bool(true)) || (TargetAtom::Arch("gfx950").eval(t) && cmp(Cmp::Eq, v[17], Val::Bool(true))),
        7 => !cmp(Cmp::Eq, v[22], Val::Bool(true)) || cmp(Cmp::Eq, v[20], Val::Bool(true)),
        8 => !(TargetAtom::Model("kimi_k3").eval(t) && cmp(Cmp::Gt, v[10], Val::Nat(16)) && cmp(Cmp::Eq, v[11], Val::Unset)) || cmp(Cmp::Eq, v[27], Val::Bool(true)),
        9 => !(cmp(Cmp::Eq, v[34], Val::Bool(true)) && cmp(Cmp::Eq, v[48], Val::Bool(true))),
        10 => !cmp(Cmp::Eq, v[35], Val::Bool(true)) || (cmp(Cmp::Eq, v[36], Val::Bool(true)) && cmp(Cmp::Eq, v[29], Val::Bool(true)) && !TargetAtom::Cap("indexer_pooled").eval(t)),
        11 => !cmp(Cmp::Eq, v[44], Val::Bool(true)) || (!cmp(Cmp::Eq, v[28], Val::Bool(true)) && !cmp(Cmp::Eq, v[29], Val::Bool(true))),
        12 => !cmp(Cmp::Eq, v[48], Val::Bool(true)) || (!cmp(Cmp::Gt, v[46], Val::Nat(1)) && !cmp(Cmp::Eq, v[47], Val::Bool(true))),
        13 => !cmp(Cmp::Eq, v[49], Val::Bool(true)) || cmp(Cmp::Eq, v[48], Val::Bool(true)),
        14 => !cmp(Cmp::Ne, v[51], Val::Unset) || cmp(Cmp::Ne, v[8], Val::Unset),
        15 => !cmp(Cmp::Eq, v[52], Val::Bool(true)) || !cmp(Cmp::Eq, v[50], Val::Bool(true)),
        16 => !cmp(Cmp::Ne, v[62], Val::Unset) || (TargetAtom::Arch("metal3").eval(t) && TargetAtom::Tp(1).eval(t) && (TargetAtom::Model("llama").eval(t) || TargetAtom::Model("qwen3").eval(t))),
        17 => !cmp(Cmp::Ne, v[62], Val::Unset) || (cmp(Cmp::Eq, v[61], Val::Unset) && !cmp(Cmp::Eq, v[1], Val::Bool(true)) && !cmp(Cmp::Eq, v[9], Val::Bool(true)) && cmp(Cmp::Eq, v[63], Val::Unset)),
        18 => !cmp(Cmp::Ne, v[67], Val::Unset) || (cmp(Cmp::Ne, v[66], Val::Unset) || TargetAtom::Cap("bundled_segment_pair").eval(t)),
        19 => !cmp(Cmp::Eq, v[65], Val::Str("1")) || cmp(Cmp::Eq, v[73], Val::Bool(true)),
        20 => !cmp(Cmp::Eq, v[64], Val::Str("1")) || cmp(Cmp::Eq, v[73], Val::Bool(true)),
        21 => !cmp(Cmp::Eq, v[75], Val::Bool(true)) || (!cmp(Cmp::Eq, v[74], Val::Bool(true)) && cmp(Cmp::Eq, v[61], Val::Unset)),
        _ => true,
    }
}

/// The first `Check::Load` constraint `v` (indexed like [`KNOBS`]) violates on `t`.
pub fn violation(v: &[Val<'_>], t: &Target) -> Option<usize> {
    (0..CONSTRAINTS.len()).find(|&i| CONSTRAINTS[i].check == Check::Load && !holds(i, v, t))
}
